namespace ToneCustoms.ShellStudio.Core;
public sealed class GeometryService { public SceneObject Wall(Vec3 p,float length=4,float height=3,float thickness=.15f)=>New("Wall",SceneObjectType.Wall,p,new(length,thickness,height)); public SceneObject Floor(Vec3 p,float width=4,float depth=4,float thickness=.1f)=>New("Floor",SceneObjectType.Floor,p,new(width,depth,thickness)); public SceneObject Ceiling(Vec3 p,float width=4,float depth=4,float thickness=.1f)=>New("Ceiling",SceneObjectType.Ceiling,p,new(width,depth,thickness)); public SceneObject Door(Vec3 p)=>New("Door",SceneObjectType.Door,p,new(.9f,.15f,2.1f)); public SceneObject Window(Vec3 p)=>New("Window",SceneObjectType.Window,p,new(1.2f,.15f,1.2f)); public SceneObject Stairs(Vec3 p)=>New("Stairs",SceneObjectType.Stairs,p,new(2,3,1.5f)); public SceneObject Room(Vec3 p,float width=5,float depth=5,float height=3)=>New("Room",SceneObjectType.Room,p,new(width,depth,height)); static SceneObject New(string n,SceneObjectType t,Vec3 p,Vec3 s)=>new(){Name=n,Type=t,Position=p,Scale=s}; public Vec3 Snap(Vec3 v,float g)=>new(MathF.Round(v.X/g)*g,MathF.Round(v.Y/g)*g,MathF.Round(v.Z/g)*g); }
